#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
named FW_GROUP_PORT fws_Allow_HQ_to_DC_servers && fail 'a port group named fws_Allow_HQ_to_DC_servers exists; nothing was written'
named FW_GROUP_IP fws_Allow_HQ_to_DC_servers_dst && fail 'an IP group named fws_Allow_HQ_to_DC_servers_dst exists; nothing was written'
named FW_GROUP_IP fws_Monitoring && fail 'an IP group named fws_Monitoring exists; nothing was written'
named FW_GROUP_IP fws_Remote_users_to_DC_dst && fail 'an IP group named fws_Remote_users_to_DC_dst exists; nothing was written'
named FW_GROUP_IP fws_Modbus_to_the_plant__2__src && fail 'an IP group named fws_Modbus_to_the_plant__2__src exists; nothing was written'
named FW_GROUP_IP fws_Block_bad_networks_dst && fail 'an IP group named fws_Block_bad_networks_dst exists; nothing was written'
named FW_GROUP_IP fws_fqdn_ftp.example.net && fail 'an IP group named fws_fqdn_ftp.example.net exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Allow_HQ_to_DC_servers_dst --set .COMMENT 'FWShift: fileserver, erp-db'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.20
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Monitoring --set .COMMENT 'FWShift: Monitoring'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.10-198.51.100.20
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Remote_users_to_DC_dst --set .COMMENT 'FWShift: not erp-db'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 0.0.0.0-10.20.0.19
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.21-255.255.255.255
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Modbus_to_the_plant__2__src --set .COMMENT 'FWShift: 10.20.0.99, 10.10.20.100-10.10.20.120'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.20.100-10.10.20.120
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.99
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Block_bad_networks_dst --set .COMMENT 'FWShift: 198.51.100.66, 203.0.113.0/24'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.66
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.0/24
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_fqdn_ftp.example.net --set .COMMENT 'FWShift: fqdn ftp.example.net'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP ftp.example.net
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_Allow_HQ_to_DC_servers --set .COMMENT 'FWShift: Allow HQ to DC servers'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8443
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
